{"ANNOUNCE_ENTRY","reg=law,swat|st=friendly,neutral|day=0,5",{"Sheriff's department! Anybody inside? Stay calm, we're here to help!","Police! If you're bitten, say so now, if not, step into the light","Deputy entering, make yourself known, nice and slow"}},
{"ANNOUNCE_ENTRY","reg=civilian,family,worker,rescue",{"Hello? Is anybody home? We're coming in, we're friendly!","Anybody in here? We're just looking for a place to rest, don't shoot!","Hello? Hello? Please don't be scared, we're not going to hurt anyone!","Hello? Sorry, sorry, it was open, anybody in here?","Anyone alive? We're coming in slow, don't panic!"}},
{"ANNOUNCE_ENTRY","reg=civilian,family,worker,rescue|tmp=fresh",{"H-hello?? We're coming in, please don't hurt us!","Is anybody here?? Please say yes, please say it's safe!"}},
{"ANNOUNCE_ENTRY","reg=family",{"Hello? Is anyone here? We're a family, please, please don't shoot!"}},
{"ANNOUNCE_ENTRY","reg=law,swat",{"Police! Anybody inside, call out!","Deputy entering, announce yourself!","Sheriff's office, coming in, show yourselves!"}},
{"ANNOUNCE_ENTRY","reg=military,elite",{"Soldiers entering, identify yourselves!","Friendly forces, coming in, sound off!"}},
{"ANNOUNCE_ENTRY","reg=outlaw,raider,gang,club,crime,prison",{"Anybody in here? Better speak up, or we start breaking things!","Hello? Hello? I'm gonna count to three, then I start shooting!","Hey!! Come out and make this easy!","Somebody in here? Easy now, we're just looking"}},
{"ANNOUNCE_ENTRY","",{"Hello? Anybody in here?","Coming in! Anybody home, sing out!","Anyone in here? We ain't looking for trouble"}},
