{"BITE_AVOIDED","reg=civilian,family,worker|mood=funny",{"Almost had me for lunch, ha, hah, ha"}},
{"BITE_AVOIDED","reg=law,swat",{"Close call, check yourself"}},
{"BITE_AVOIDED","reg=military,elite",{"Near miss, check for exposure"}},
